# Check patterns of matching reflection in 28x28 core across axes
h=[]; v=[]
for r in range(2,30):
 for c in range(2,30):
  a=grid[r][c]; b=grid[r][31-c]
  if a!=6 and b!=6: h.append((a==b,a,b,r,c))
for r in range(2,30):
 for c in range(2,30):
  a=grid[r][c]; b=grid[31-r][c]
  if a!=6 and b!=6:v.append((a==b,a,b,r,c))
sum(x[0] for x in h),len(h),sum(x[0] for x in v),len(v),[x for x in h if not x[0]][:10],[x for x in v if not x[0]][:10]

out=[row[:] for row in grid]
coords=[(r,c) for r in range(30) for c in range(30) if grid[r][c]==6]
unresolved=[]; conflicts=[]
for r,c in coords:
    opts=[]
    # Applicable symmetries: central core vertical/horiz; top two rows only horizontal
    if c>=2:
        b=grid[r][31-c]
        if b!=6: opts.append(b)
    if r>=2 and c>=2:
        b=grid[31-r][c]
        if b!=6: opts.append(b)
    if r>=2 and c>=2:
        b=grid[31-r][31-c]
        if b!=6: opts.append(b)
    if not opts: unresolved.append((r,c))
    elif len(set(opts))>1: conflicts.append((r,c,opts))
    else: out[r][c]=opts[0]
len(coords),len(unresolved),unresolved[:20],len(conflicts),conflicts[:5]

# test diagonal symmetry across main core, ignoring masks
pairs=[]
for r in range(2,30):
 for c in range(2,30):
  a,b=grid[r][c],grid[c][r]
  if a!=6 and b!=6: pairs.append((a==b,r,c,a,b))
sum(p[0] for p in pairs),len(pairs),[p for p in pairs if not p[0]][:12]

diag=[]
for r in range(30):
 for c in range(30):
  a,b=grid[r][c],grid[c][r]
  if a!=6 and b!=6: diag.append((a==b,r,c,a,b))
sum(x[0] for x in diag),len(diag),[x for x in diag if not x[0]][:30]

def orbit(r,c):
 pts={(r,c)}
 # transposition toggles coordinates
 for _ in range(1):
  pts |= {(b,a) for a,b in list(pts)}
 # any reflection in the core applies only to coordinates >=2; reflections may be applied to row or col
 # closure using generators on each pair
 changed=True
 while changed:
  old=set(pts)
  for a,b in old:
   if a>=2: pts.add((31-a,b))
   if b>=2: pts.add((a,31-b))
   pts.add((b,a))
  changed=pts!=old
 return pts
un=[]; amb=[]; fills={}
for r,c in coords:
 opts={grid[a][b] for a,b in orbit(r,c) if grid[a][b]!=6}
 if not opts: un.append((r,c,orbit(r,c)))
 elif len(opts)>1: amb.append((r,c,opts))
 else: fills[(r,c)]=opts.pop()
len(coords),len(fills),len(un),len(amb),[(r,c,len(o)) for r,c,o in un[:5]],amb[:5]
